import java.math.BigInteger;

public class Combinatorics { 
  // Method to compute C(n, k)
  public static BigInteger combination(int n, int k) { ... } 
}

/* Calculate Fibonacci numbers using iterative method */
int a = 0, b = 1, sum = 0;
for (int i = 2; i < n; i++) {
  sum = a + b;
  a = b;
  b = sum;
}

def compute_gcd(a, b):
    # Recursive function to compute GCD using Euclid's algorithm
    return a if b == 0 else compute_gcd(b, a % b)

package main

import "fmt"
// Program to compute the factorial of a number using a recursive function
func factorial(n int) int { if n <= 1 { return 1 } else { return n * factorial(n-1) } }

public class AlgorithmExample {
   // Compute combinatorial values and probability
   public static double probability(int n, int k, double p) {
      int c = computeCombination(n, k);
      return c * Math.pow(p, k) * Math.pow(1-p, n-k);
   }
   // Assume computeCombination is implemented
}

